$root=Join-Path $PWD 'IndicatorCodeExamples';$utf=New-Object Text.UTF8Encoding($false)
$p=Join-Path $root 'OrbStrategyUserMetrics.mqh';$s=[IO.File]::ReadAllText($p)
$s=$s.Replace('string OrbUserRuntimeMetricKey()', 'string OrbClockMetricMeta(double offset,int profile,int broker,int exchange,int session)'+"`r`n"+'{if(offset==0&&profile==0&&broker==0&&exchange==0&&session==0)return "";return "|CLOCK="+DoubleToString(offset,8)+","+(string)profile+","+(string)broker+","+(string)exchange+","+(string)session;}'+"`r`n"+'string OrbUserRuntimeMetricKey()')
$s=$s.Replace('   return OrbUserMetricKey(_Symbol,(int)_Period,OrbCustomInputSignature(),OrbCustomRuntimeDump(),p);', '   double saved=g_orbStrategyTimezone;g_orbStrategyTimezone=0;string signature=OrbCustomInputSignature();g_orbStrategyTimezone=saved;'+"`r`n"+'   signature+=OrbClockMetricMeta(OrbBrokerOffsetHours(),(int)OrbClockProfile(),(int)OrbClockBrokerSeason(),(int)OrbClockExchangeSeason(),g_orbClockSession);'+"`r`n"+'   return OrbUserMetricKey(_Symbol,(int)_Period,signature,OrbCustomRuntimeDump(),p);')
$s=$s.Replace('r.inputSignature,r.runtime,r.preset)', 'r.inputSignature+OrbClockMetricMeta(r.brokerOffset,r.clockProfile,r.brokerSeason,r.exchangeSeason,r.clockSession),r.runtime,r.preset)')
[IO.File]::WriteAllText($p,$s,$utf)
$p=Join-Path $root 'macrossover_orb/OrbStrategyUserMetrics.mqh';$s=[IO.File]::ReadAllText($p)
$s=$s.Replace('string OrbUserRuntimeMetricKey()', 'string MaEntryMetricMeta(bool independent,int maximum){return !independent&&maximum==1?"":"|MAENTRY1="+(independent?"1":"0")+","+(string)maximum;}'+"`r`n"+'string OrbUserRuntimeMetricKey()')
$s=$s.Replace('OrbCustomInputSignature(),OrbCustomRuntimeDump(),p)', 'OrbCustomInputSignature()+MaEntryMetricMeta(g_maIndependent,g_maMaxConsecutive),OrbCustomRuntimeDump(),p)')
$s=$s.Replace('r.inputSignature,r.runtime,r.preset)', 'r.inputSignature+MaEntryMetricMeta(r.independent,r.maxSeries),r.runtime,r.preset)')
[IO.File]::WriteAllText($p,$s,$utf)
